\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc,shapes.callouts,shapes.arrows,decorations.pathreplacing}
\pagestyle{empty}

%% ── Dark-Mode Developer Theme ─────────────────────────────────────────────────
\definecolor{darkbg}{HTML}{0D1117}        % GitHub-dark background
\definecolor{panelbg}{HTML}{161B22}       % slightly lighter panels
\definecolor{panelbg2}{HTML}{1C2128}      % alternate panel shade
\definecolor{electricblue}{HTML}{58A6FF}  % electric blue accent
\definecolor{teal}{HTML}{2DD4BF}          % teal accent
\definecolor{amber}{HTML}{F59E0B}         % amber for warnings
\definecolor{amber2}{HTML}{FCD34D}        % lighter amber
\definecolor{gridline}{HTML}{21262D}      % subtle grid lines
\definecolor{textprimary}{HTML}{E6EDF3}   % primary text
\definecolor{textsecondary}{HTML}{8B949E} % secondary text
\definecolor{texttert}{HTML}{6E7681}      % tertiary text
\definecolor{borderblue}{HTML}{1F6FEB}    % deep blue for borders
\definecolor{borderteal}{HTML}{0D9488}    % deep teal for borders
\definecolor{borderamber}{HTML}{D97706}   % deep amber for borders
\definecolor{chrome55color}{HTML}{3B5BDB} % timeline start
\definecolor{chrome146color}{HTML}{10B981}% timeline end
\definecolor{warningbg}{HTML}{1C1506}     % amber warning background
\definecolor{warningborder}{HTML}{F59E0B} % amber warning border
\definecolor{statbg}{HTML}{0C1A2E}        % deep blue stat background
\definecolor{greenbg}{HTML}{052E16}       % deep green bg
\definecolor{purplebg}{HTML}{1E0A3C}      % deep purple bg
\definecolor{rowdark}{HTML}{1C2128}       % table row dark
\definecolor{rowlight}{HTML}{161B22}      % table row light

\pagecolor{darkbg}
\color{textprimary}

%% ── List Styling ──────────────────────────────────────────────────────────────
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{electricblue}\small$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{teal}\bfseries\arabic*.}}

%% ── Card Styles ───────────────────────────────────────────────────────────────
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=panelbg,
    borderline west={4pt}{0pt}{electricblue},
    borderline north={1pt}{0pt}{gridline},
    borderline south={1pt}{0pt}{gridline},
    left=14pt, right=12pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{electricblue},
    coltitle=electricblue, colbacktitle=panelbg2,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={electricblue!40},
    valign=top,
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=panelbg,
    borderline west={4pt}{0pt}{teal},
    borderline north={1pt}{0pt}{gridline},
    borderline south={1pt}{0pt}{gridline},
    left=14pt, right=12pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=panelbg2,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={teal!40},
    valign=top,
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=warningbg,
    borderline west={4pt}{0pt}{amber},
    borderline={1pt}{0pt}{amber!30},
    left=14pt, right=12pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=warningbg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={amber!40},
    valign=top,
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=panelbg2,
    borderline west={4pt}{0pt}{textsecondary},
    borderline north={1pt}{0pt}{gridline},
    borderline south={1pt}{0pt}{gridline},
    left=14pt, right=12pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{textprimary},
    coltitle=textprimary, colbacktitle=panelbg2,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={textsecondary!40},
    valign=top,
  },
}

%% ── Helpers ───────────────────────────────────────────────────────────────────
\newcommand{\mono}[1]{{\fontfamily{lmtt}\selectfont\small #1}}
\newcommand{\highlight}[2]{%
  \colorbox{#1}{\parbox{0.91\linewidth}{\fontsize{20}{26}\selectfont #2}}%
}
\newcommand{\statbox}[3]{%
  \begin{tcolorbox}[enhanced,arc=6pt,boxrule=1pt,
    colback=#1,colframe=#2,
    left=8pt,right=8pt,top=6pt,bottom=6pt,
    halign=center,valign=center]
    {\fontsize{52}{62}\selectfont\bfseries\color{#2} #3}
  \end{tcolorbox}%
}
\newcommand{\yearband}[4]{%
  % #1=year #2=chrome range #3=runs #4=bar width factor
  \noindent\colorbox{panelbg2}{\parbox{0.92\linewidth}{%
    \fontsize{19}{24}\selectfont
    \textcolor{electricblue}{\textbf{#1}}\quad
    \textcolor{textsecondary}{\mono{Chrome #2}}\hfill
    \textcolor{teal}{\textbf{#3 runs}}%
  }}\vspace{2pt}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

%% ════════════════════════════════════════════════════════════════════════════
%% TITLE BAR — rows 1–3
%% ════════════════════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=darkbg, colframe=darkbg, arc=0pt, boxrule=0pt,
  borderline south={2pt}{0pt}{electricblue!50},
  left=28pt, right=28pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row3}{
  % Monospace top label
  {\fontsize{18}{22}\selectfont\color{textsecondary}\fontfamily{lmtt}\selectfont
   github.com/krausest/js-framework-benchmark \quad$\bullet$\quad Open Source \quad$\bullet$\quad 2017–2026}\\[6pt]
  % Main title
  {\fontsize{52}{62}\selectfont\bfseries\color{textprimary}
   JS Framework Benchmark}\\[4pt]
  {\fontsize{30}{36}\selectfont\color{electricblue}
   5 Years of Browser Performance Testing}\\[6pt]
  {\fontsize{20}{26}\selectfont\color{textsecondary}
   Tracking JavaScript framework DOM performance across 8 years of Chrome releases}
}

%% ════════════════════════════════════════════════════════════════════════════
%% STAT BANNER — rows 3–5
%% ════════════════════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=panelbg2, colframe=panelbg2, arc=0pt, boxrule=0pt,
  borderline south={2pt}{0pt}{gridline},
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  halign=center, valign=center,
]{name=stats, column=1, span=3, between=row3 and row5}{
  \begin{minipage}[c]{0.195\linewidth}\centering
    \begin{tcolorbox}[enhanced,arc=4pt,boxrule=1.5pt,
      colback=statbg,colframe=electricblue,
      left=6pt,right=6pt,top=5pt,bottom=5pt,
      halign=center,valign=center]
      {\fontsize{44}{52}\selectfont\bfseries\color{electricblue} 60+}\\[1pt]
      {\fontsize{16}{20}\selectfont\color{textprimary} Official Runs}\\[1pt]
      {\fontsize{13}{16}\selectfont\color{textsecondary} Chrome 55 → 146}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.195\linewidth}\centering
    \begin{tcolorbox}[enhanced,arc=4pt,boxrule=1.5pt,
      colback=greenbg,colframe=teal,
      left=6pt,right=6pt,top=5pt,bottom=5pt,
      halign=center,valign=center]
      {\fontsize{44}{52}\selectfont\bfseries\color{teal} 8}\\[1pt]
      {\fontsize{16}{20}\selectfont\color{textprimary} Years Active}\\[1pt]
      {\fontsize{13}{16}\selectfont\color{textsecondary} 2017 – 2026}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.195\linewidth}\centering
    \begin{tcolorbox}[enhanced,arc=4pt,boxrule=1.5pt,
      colback=warningbg,colframe=amber,
      left=6pt,right=6pt,top=5pt,bottom=5pt,
      halign=center,valign=center]
      {\fontsize{44}{52}\selectfont\bfseries\color{amber} 118}\\[1pt]
      {\fontsize{16}{20}\selectfont\color{textprimary} Method Changed}\\[1pt]
      {\fontsize{13}{16}\selectfont\color{textsecondary} Weighted Geo. Mean}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.195\linewidth}\centering
    \begin{tcolorbox}[enhanced,arc=4pt,boxrule=1.5pt,
      colback=purplebg,colframe=electricblue!60!teal,
      left=6pt,right=6pt,top=5pt,bottom=5pt,
      halign=center,valign=center]
      {\fontsize{44}{52}\selectfont\bfseries\color{electricblue!60!teal} 95\%+}\\[1pt]
      {\fontsize{16}{20}\selectfont\color{textprimary} macOS Runs}\\[1pt]
      {\fontsize{13}{16}\selectfont\color{textsecondary} 2 Windows only}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.155\linewidth}\centering
    \begin{tcolorbox}[enhanced,arc=4pt,boxrule=1.5pt,
      colback=greenbg,colframe=teal!70!electricblue,
      left=6pt,right=6pt,top=5pt,bottom=5pt,
      halign=center,valign=center]
      {\fontsize{44}{52}\selectfont\bfseries\color{teal!70!electricblue} 12}\\[1pt]
      {\fontsize{16}{20}\selectfont\color{textprimary} Runs in 2025}\\[1pt]
      {\fontsize{13}{16}\selectfont\color{textsecondary} Most active year}
    \end{tcolorbox}
  \end{minipage}
}

%% ════════════════════════════════════════════════════════════════════════════
%% COLUMN 1
%% ════════════════════════════════════════════════════════════════════════════

%% — What Is the Benchmark? (rows 5–8) —
\posterbox[bluecard, title={\fontsize{28}{34}\selectfont\bfseries\color{electricblue} What Is the JS Framework Benchmark?}
]{name=overview, column=1, between=row5 and row8}{
  \fontsize{21}{28}\selectfont\color{textprimary}
  The most widely-referenced open-source benchmark for comparing JavaScript web frameworks on real-world DOM operations.
  \vspace{6pt}

  \colorbox{panelbg2}{\parbox{0.91\linewidth}{%
    \fontsize{18}{24}\selectfont\color{textsecondary}
    \textcolor{electricblue}{\bfseries Maintained by:}\ Stefan Krause\\
    \textcolor{electricblue}{\bfseries Hosted:}\ GitHub Pages\\
    \textcolor{electricblue}{\bfseries Browser:}\ Real Chrome, controlled CPU throttle
  }}\vspace{5pt}

  \fontsize{19}{26}\selectfont\color{textprimary}
  \textbf{Operations measured:}
  \begin{itemize}[itemsep=3pt,topsep=3pt]
    \item Create 1,000 rows
    \item Partial update (every 10th row)
    \item Row select / swap / remove
    \item Startup time
  \end{itemize}
  \vspace{4pt}
  \colorbox{panelbg2}{\parbox{0.91\linewidth}{%
    \fontsize{19}{25}\selectfont
    \textcolor{teal}{\bfseries Keyed} vs \textcolor{amber}{\bfseries Non-Keyed} —
    two implementation modes tracked separately
  }}
}

%% — Runs by Year table (rows 8–14) —
\posterbox[tealcard, title={\fontsize{28}{34}\selectfont\bfseries\color{teal} Official Runs by Year}
]{name=runsyear, column=1, between=row8 and row14}{
  \fontsize{19}{25}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \setlength{\tabcolsep}{5pt}
  \begin{tabular}{p{0.16\linewidth}p{0.31\linewidth}p{0.12\linewidth}p{0.25\linewidth}}
    \rowcolor{panelbg2}
    \textcolor{electricblue}{\bfseries Year} &
    \textcolor{electricblue}{\bfseries Chrome} &
    \textcolor{electricblue}{\bfseries Runs} &
    \textcolor{electricblue}{\bfseries Notes} \\
    \rowcolor{rowdark}
    \textcolor{textsecondary}{2017–19} & \mono{55, 58, 62, 69} & \textcolor{teal}{4} & \textcolor{textsecondary}{Early era} \\
    \rowcolor{rowlight}
    \textcolor{textsecondary}{2020} & \mono{83 – 87} & \textcolor{teal}{5} & \textcolor{textsecondary}{→ GitHub Pages} \\
    \rowcolor{rowdark}
    \textcolor{textsecondary}{2021} & \mono{88 – 96} & \textcolor{teal}{9} & \textcolor{textsecondary}{Monthly cadence} \\
    \rowcolor{rowlight}
    \textcolor{textsecondary}{2022} & \mono{97 – 108} & \textcolor{teal}{13} & \textcolor{textsecondary}{+2 Windows} \\
    \rowcolor{rowdark}
    \textcolor{amber}{\bfseries 2023} & \mono{109 – 120} & \textcolor{teal}{12} & \textcolor{amber}{\bfseries Method change!} \\
    \rowcolor{rowlight}
    \textcolor{textsecondary}{2024} & \mono{121 – 131} & \textcolor{teal}{12} & \textcolor{textsecondary}{+1 Windows} \\
    \rowcolor{rowdark}
    \textcolor{textprimary}{\bfseries 2025} & \mono{132 – 143} & \textcolor{teal}{\bfseries 12} & \textcolor{teal}{\bfseries Most active} \\
    \rowcolor{rowlight}
    \textcolor{textsecondary}{2026} & \mono{144 – 146} & \textcolor{teal}{3} & \textcolor{textsecondary}{Ongoing...} \\
  \end{tabular}
  \vspace{6pt}

  \colorbox{panelbg2}{\parbox{0.91\linewidth}{%
    \fontsize{18}{24}\selectfont\color{textsecondary}
    Total: \textcolor{electricblue}{\bfseries 60+ runs} across
    \textcolor{teal}{\bfseries 8 years} of Chrome releases
  }}
}

%% — Platform Coverage (rows 14–17) —
\posterbox[darkcard, title={\fontsize{28}{34}\selectfont\bfseries\color{textprimary} Platform Coverage}
]{name=platform, column=1, between=row14 and row17}{
  \fontsize{21}{28}\selectfont\color{textprimary}

  \colorbox{panelbg}{\parbox{0.91\linewidth}{%
    \fontsize{19}{25}\selectfont
    \begin{center}
      \textcolor{teal}{\fontsize{36}{44}\selectfont\bfseries 95\%+}\\[2pt]
      \textcolor{textprimary}{macOS (OSX) runs}
    \end{center}
  }}\vspace{5pt}

  \colorbox{warningbg}{\parbox{0.91\linewidth}{%
    \fontsize{18}{24}\selectfont\color{amber2}
    \textbf{Windows exceptions:}\\
    \textcolor{textprimary}{$\bullet$ Chrome 104 — Windows (2022)}\\
    \textcolor{textprimary}{$\bullet$ Chrome 121 — Windows (2024)}
  }}\vspace{4pt}

  \fontsize{18}{24}\selectfont\color{textsecondary}
  Results primarily reflect macOS + Chrome performance characteristics.
}

%% — Key Takeaways (rows 17–bottom) —
\posterbox[tealcard, title={\fontsize{28}{34}\selectfont\bfseries\color{teal} Key Takeaways for Developers}
]{name=takeaways, column=1, between=row17 and bottom}{
  \fontsize{20}{27}\selectfont\color{textprimary}
  \begin{enumerate}[itemsep=5pt,topsep=2pt,label={\color{teal}\bfseries\arabic*.}]
    \item \textbf{Compare within same Chrome version} — methodology differs across releases
    \item \textbf{Consult Chrome 146} for current framework standings
    \item \textbf{Weighted geo. mean} (since Chrome 118) gives balanced scores
    \item \textbf{Keyed vs non-keyed} — recent odd runs are keyed-only
    \item \textbf{60+ data points} — longest-running JS perf tracker
  \end{enumerate}
}

%% ════════════════════════════════════════════════════════════════════════════
%% COLUMN 2 — Timeline (the centerpiece)
%% ════════════════════════════════════════════════════════════════════════════

\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=panelbg, colframe=panelbg,
  borderline north={1pt}{0pt}{gridline},
  borderline south={1pt}{0pt}{gridline},
  left=14pt, right=12pt, top=6pt, bottom=6pt,
  valign=top,
]{name=timeline, column=2, between=row5 and bottom}{

  %% Header
  {\fontsize{28}{34}\selectfont\bfseries\color{electricblue}
   Benchmark Timeline: Chrome 55 \textrightarrow\ 146}\vspace{8pt}

  \noindent\colorbox{panelbg2}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont\color{textsecondary}
    Each entry = one official benchmark run \quad
    \textcolor{amber}{\bfseries $\bigstar$} = methodology milestone
  }}\vspace{8pt}

  %% ── Timeline rendered as a vertical strip ──────────────────────────────
  \begin{tikzpicture}[x=1mm, y=1mm, font=\fontsize{17}{21}\selectfont]

    % Parameters
    \def\lineX{8}      % x of vertical spine
    \def\dotR{2.0}     % dot radius
    \def\rowH{10.5}    % mm per entry
    \def\labelX{14}    % x of label start
    \def\rightX{130}   % right edge
    \def\barStart{68}  % x where bar starts
    \def\barH{5}       % bar height
    \def\maxBarW{58}   % max bar width (for 13 runs)

    % Vertical spine
    \draw[electricblue!30, line width=1.5pt] (\lineX,0) -- (\lineX,-520);

    % ── Entries: (chrome, year, runs, label, isWarning, isWindows, barW) ──
    % Row offsets from top (y = -row * rowH)
    % 2017-2019 era
    \foreach \chrome/\yr/\runs/\note/\warn/\barw/\rownum in {
      55/2017/4/{Early era}/0/17.7/0,
      58/2017/4/{}/0/17.7/1,
      62/2018/4/{}/0/17.7/2,
      69/2019/4/{}/0/17.7/3
    }{
      \pgfmathsetmacro{\yy}{-\rownum * \rowH - 5}
      % dot
      \fill[electricblue] (\lineX,\yy) circle (\dotR pt);
      % chrome label
      \node[anchor=west, text=textprimary!80, inner sep=0] at (\labelX,\yy)
        {\fontfamily{lmtt}\selectfont\fontsize{15}{18}\selectfont Chrome \chrome};
      % year
      \node[anchor=west, text=textsecondary, inner sep=0] at (50,\yy)
        {\fontsize{14}{17}\selectfont\yr};
      % bar
      \fill[electricblue!40] (\barStart,\yy-2.5) rectangle (\barStart+\barw,\yy+2.5);
      % runs
      \node[anchor=west, text=teal, inner sep=0] at (\barStart+\barw+2,\yy)
        {\fontsize{14}{17}\selectfont\runs};
    }

